/**
 * Architecture Contract: API Routes
 *
 * Tests the HTTP interface of the Express app.
 * Verifies: route existence, public vs auth boundaries, response shapes.
 *
 * These tests import the Express app and use supertest — they exercise
 * the full middleware stack with all services in mock mode.
 *
 * Generated by /architect
 */

const request = require('supertest');
const app = require('../../src/index');
const blockchainService = require('../../src/services/blockchain');
const crypto = require('crypto');

// Helper: create a mock SIWE auth token (accepted in test/dev mode)
function createMockAuthToken(address) {
  const message = `localhost wants you to sign in with your Ethereum account:\n${address}\n\nSign in to NFTmarket\n\nURI: http://localhost:3000\nVersion: 1\nChain ID: 31337\nNonce: test123\nIssued At: ${new Date().toISOString()}`;
  const signature = '0x' + crypto.createHash('sha256').update(message).digest('hex');
  return Buffer.from(JSON.stringify({ message, signature })).toString('base64');
}

describe('API route interface contract', () => {
  beforeEach(() => {
    blockchainService.resetMock();
  });

  // ── Public Routes ──

  test('GET / returns health status', async () => {
    const res = await request(app).get('/');
    expect(res.status).toBe(200);
    expect(res.body.status).toBe('healthy');
    expect(res.body.service).toBe('nftmarket-api');
  });

  test('GET /health returns ok', async () => {
    const res = await request(app).get('/health');
    expect(res.status).toBe(200);
    expect(res.body.status).toBe('ok');
  });

  test('GET /api/verify/:tokenId is public (no auth required)', async () => {
    const res = await request(app).get('/api/verify/999');
    // 404 is expected for nonexistent token, but NOT 401
    expect(res.status).not.toBe(401);
  });

  test('GET /api/marketplace is public', async () => {
    const res = await request(app).get('/api/marketplace');
    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('listings');
    expect(Array.isArray(res.body.listings)).toBe(true);
  });

  test('GET /api/marketplace/eip712/domain is public', async () => {
    const res = await request(app).get('/api/marketplace/eip712/domain');
    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('domain');
  });

  test('GET /api/marketplace/nonce/:address is public', async () => {
    const res = await request(app).get('/api/marketplace/nonce/0x1234567890123456789012345678901234567890');
    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('nonce');
  });

  test('GET /api/mint/price is public', async () => {
    const res = await request(app).get('/api/mint/price');
    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('display');
    expect(res.body).toHaveProperty('commercial');
    expect(res.body).toHaveProperty('transfer');
  });

  test('GET /api/generate/styles is public', async () => {
    const res = await request(app).get('/api/generate/styles');
    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('styles');
  });

  test('GET /api/gallery is public', async () => {
    const res = await request(app).get('/api/gallery');
    expect(res.status).toBe(200);
  });

  // ── Auth Boundary ──

  test('POST /api/mint requires authentication', async () => {
    const res = await request(app).post('/api/mint');
    expect(res.status).toBe(401);
  });

  test('POST /api/detect/blind requires authentication', async () => {
    const res = await request(app).post('/api/detect/blind');
    expect(res.status).toBe(401);
  });

  test('POST /api/generate requires authentication', async () => {
    const res = await request(app).post('/api/generate');
    expect(res.status).toBe(401);
  });

  // ── Response Shape Contracts ──

  test('GET /api/marketplace listing response shape', async () => {
    // Mint and list a token to have data
    const wallet = '0x1234567890123456789012345678901234567890';
    const [r] = await blockchainService.reserveTokenId();
    await blockchainService.mint(r.tokenId, wallet, 'ipfs://uri', '0xh1', 'ipfs://img');
    await blockchainService.listToken(r.tokenId, '1000000000000000000', 0, '0xlh', 0, '0xsig', wallet);

    const res = await request(app).get('/api/marketplace');
    expect(res.status).toBe(200);

    const listing = res.body.listings[0];
    expect(listing).toHaveProperty('tokenId');
    expect(listing).toHaveProperty('price');
    expect(listing).toHaveProperty('priceEth');
    expect(listing).toHaveProperty('seller');
    expect(listing).toHaveProperty('licenseType');
  });

  test('GET /api/marketplace response includes contract info', async () => {
    const res = await request(app).get('/api/marketplace');
    expect(res.body).toHaveProperty('contract');
    expect(res.body.contract).toHaveProperty('name');
    expect(res.body.contract).toHaveProperty('address');
    expect(res.body.contract).toHaveProperty('chainId');
  });

  // ── Error Handler ──

  test('unknown routes return 404', async () => {
    const res = await request(app).get('/api/nonexistent');
    expect(res.status).toBe(404);
  });
});
